class DetailedSiteViewPageViewPanel(ViewPanel):
    _RESET_SITE_BUTTON_XPATH = "//ui-button[@a-text='Reset Site']/button"
    _BASE_HW_XPATH = "//div[contains(text(), '{}')]"
    _BASE_EXT_XPATH = "//div[@class='runtime-view-container']//*[contains(text(), '{}')]"
    SITE_LINK = '//*[@id="site-links"]//*[contains(@class, "in-relation")]'
    CELL_LINK = '//*[@id="cell-links"]//*[contains(@class, "in-relation")]'

    def __init__(self, driver):
        super(DetailedSiteViewPageViewPanel, self).__init__(driver)

    def reset_site(self, with_graceful=False, without_radio_reset=False):
        ResetModalCommonOperation(self.driver).click_reset_and_confirm(
            with_graceful, self._RESET_SITE_BUTTON_XPATH, without_radio_reset=without_radio_reset)

    def block_site(self):
        BlockAndUnblockSiteModal(self.driver).click_block_and_confirm()

    def unblock_site(self):
        BlockAndUnblockSiteModal(self.driver).click_unblock_and_confirm()

    def show_hardware_detail_panel(self, hw_name, hw_xpath=_BASE_HW_XPATH):
        self.show_detail_panel(hw_xpath.format(hw_name))

    def show_tls_detail_panel(self, tls_name):
        self.show_detail_panel(self._BASE_EXT_XPATH.format(tls_name))

    def get_channel_relation_info(self):
        info = {}
        elem = self.driver.find_element_by_xpath(self.SITE_LINK)
        site_link_source = elem.get_attribute('source')
        site_link_target = elem.get_attribute('target')
        info.update({'site': {site_link_source: site_link_target}})

        cell_links = []
        for elem in self.driver.find_elements_by_xpath(self.CELL_LINK):
            cell_link_source = elem.get_attribute('source')
            cell_link_target = elem.get_attribute('target')
            cell_links.append({cell_link_source: cell_link_target})
        info.update({'cell': cell_links})
        return info

    def _show_detail_panel(self, hw_type, hw_index, hw_running_index=None):
        if hw_index is None:
            hw_name = hw_type
        else:
            hw_name = "{}-{}".format(hw_type, hw_index)
        hw_xpath = "//div[contains(text(), '{} /')]".format(hw_name)

        if hw_running_index is not None:
            hw_xpath = ('//*[contains(text(), "{0} /") and '
                        'substring(text(), string-length(text()) - string-length("{1}_R-{2}") +1) = "{1}_R-{2}"]')
            hw_xpath = hw_xpath.format(hw_name, hw_type, hw_running_index)
        self._wait_for_element_by((By.XPATH, hw_xpath))
        self.show_detail_panel(hw_xpath)


class DetailedSiteViewPageDetailPanel(DetailPanel):
    _RESET_BUTTON_XPATH = "//ui-button[@a-text='Reset']/button"
    _LOCK_OR_UNLOCK_BUTTON_XPATH = '//ui-button[@a-text="Lock" or @a-text="Unlock"]/button'
    _BLOCK_OR_UNBLOCK_BUTTON_XPATH = '//ui-button[@a-text="Block" or @a-text="Unblock"]/button'
    _CALIBRATE_BUTTON_XPATH = "//ui-button[@a-text='Calibrate']/button"
    _SET_ANGLES_BUTTON_XPATH = "//ui-button[@a-text='Set Angles']/button"
    LOCK_STATUS = "Lock"
    UNLOCK_STATUS = "Unlock"
    BLOCK_STATUS = "Block"
    UNBLOCK_STATUS = "Unblock"
    SHOW_CHANNEL_RELATION = '//*[@class="hardware-details-toolbar"]//button[contains(text(), "Show Channel Relation")]'
    HIDE_CHANNEL_RELATION = '//*[@class="hardware-details-toolbar"]//button[contains(text(), "Hide Channel Relation")]'

    def __init__(self, driver):
        super(DetailedSiteViewPageDetailPanel, self).__init__(driver)

    def lock_hardware(self, hw_name, timeout=120, lock_unlock_button_xpath=None):
        if not lock_unlock_button_xpath:
            lock_unlock_button_xpath = self._LOCK_OR_UNLOCK_BUTTON_XPATH

        current_status = self.get_text_by_xpath(lock_unlock_button_xpath)
        if self.LOCK_STATUS != current_status:
            logging.warning("{} is locked now, no need to lock again".format(hw_name))
            return self.LOCK_STATUS

        LockModalCommonOperation(self.driver).click_lock_and_confirm(lock_unlock_button_xpath)
        self.wait_for_text_present_in_element((By.XPATH, lock_unlock_button_xpath),
                                              self.UNLOCK_STATUS, timeout)
        return self.LOCK_STATUS

    def unlock_hardware(self, hw_name, timeout=120, lock_unlock_button_xpath=None):
        if not lock_unlock_button_xpath:
            lock_unlock_button_xpath = self._LOCK_OR_UNLOCK_BUTTON_XPATH

        current_status = self.get_text_by_xpath(lock_unlock_button_xpath)
        if self.UNLOCK_STATUS != current_status:
            logging.warning("{} is unlocked now, no need to unlock again".format(hw_name))
            return self.UNLOCK_STATUS

        UnlockModalCommonOperation(self.driver).click_unlock_and_confirm(lock_unlock_button_xpath)
        self.wait_for_text_present_in_element((By.XPATH, lock_unlock_button_xpath),
                                              self.LOCK_STATUS,
                                              timeout)
        return self.UNLOCK_STATUS

    def block_hardware(self, hw_name, timeout=120, block_unblock_button_xpath=None):
        if not block_unblock_button_xpath:
            block_unblock_button_xpath = self._BLOCK_OR_UNBLOCK_BUTTON_XPATH

        current_status = self.get_text_by_xpath(block_unblock_button_xpath)
        if self.BLOCK_STATUS != current_status:
            logging.warning("{} is blocked now, no need to block again".format(hw_name))
        else:
            LockModalCommonOperation(self.driver).click_lock_and_confirm(block_unblock_button_xpath)
            self.wait_for_text_present_in_element((By.XPATH, block_unblock_button_xpath),
                                                  self.UNBLOCK_STATUS, timeout)
        return self.BLOCK_STATUS

    def unblock_hardware(self, hw_name, timeout=120, block_unblock_button_xpath=None):
        if not block_unblock_button_xpath:
            block_unblock_button_xpath = self._BLOCK_OR_UNBLOCK_BUTTON_XPATH

        current_status = self.get_text_by_xpath(block_unblock_button_xpath)
        if self.UNBLOCK_STATUS != current_status:
            logging.warning("{} is unblocked now, no need to unblock again".format(hw_name))
        else:
            UnlockModalCommonOperation(self.driver).click_unlock_and_confirm(block_unblock_button_xpath)
            self.wait_for_text_present_in_element((By.XPATH, block_unblock_button_xpath),
                                                  self.BLOCK_STATUS,
                                                  timeout)
        return self.UNBLOCK_STATUS

    def reset_hardware(self, with_graceful, timeout):
        self.wait_until_element_is_clickable(self._RESET_BUTTON_XPATH, timeout=timeout)
        ResetModalCommonOperation(self.driver).click_reset_and_confirm(with_graceful, self._RESET_BUTTON_XPATH)

    def reset_ald(self, reset_type):
        self.click_enabled_element((By.XPATH, self._RESET_BUTTON_XPATH))
        AldResetModal(self.driver).wait_until_reset_modal_appear()
        AldResetModal(self.driver).reset_ald(reset_type)

    def calibrate_retu(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._CALIBRATE_BUTTON_XPATH))
        CalibrateRetuModal(self.driver).wait_until_calibrate_modal_appear()
        CalibrateRetuModal(self.driver).calibrate()
        self.wait_for_enable((By.XPATH, self._CALIBRATE_BUTTON_XPATH), timeout)
        return True

    def set_retu_angles(self, timeout=60, **configuration):
        self.click_enabled_element((By.XPATH, self._SET_ANGLES_BUTTON_XPATH))
        SetAngleModal(self.driver).wait_until_set_angle_modal_appear()
        SetAngleModal(self.driver).configure_angles(**configuration)
        SetAngleModal(self.driver).save()
        self.wait_for_enable((By.XPATH, self._SET_ANGLES_BUTTON_XPATH), timeout)
        return True

    def show_channel_relation(self):
        self.click_enabled_element((By.XPATH, self.SHOW_CHANNEL_RELATION))

    def hide_channel_relation(self):
        self.click_enabled_element((By.XPATH, self.HIDE_CHANNEL_RELATION))


class CellsPage(NavigatablePage):
    """
    As a class will be called by BtsStatus, all operations on Cells will be implemented under this class.
    """
    _MENU_ROUTE_LIST = ['BTS Status', 'Site Runtime View', 'Cells']
    _GLOBAL_CELL_ID = 'Global cell ID'
    _CELL_ID = 'Cell ID'
    _GSM_SECTOR_ID = 'GSM sector ID'

    def __init__(self, driver):
        super(CellsPage, self).__init__(driver)
        self._navigation_panel = CellsPageNavigationPanel(driver)
        self._view_panel = CellsPageViewPanel(driver)
        self._detail_panel = CellsPageDetailPanel(driver)

    def lock_cell(self, cell_id, timeout=60):
        cell_xpath, _ = self._get_cell_xpath_and_info_by_id(cell_id)
        self._view_panel.show_detail_panel(cell_xpath)
        self._detail_panel.lock_cell(timeout)

    def unlock_cell(self, cell_id, timeout=60):
        cell_xpath, _ = self._get_cell_xpath_and_info_by_id(cell_id)
        self._view_panel.show_detail_panel(cell_xpath)
        self._detail_panel.unlock_cell(timeout)

    def reset_cell(self, cell_id, with_graceful=False, timeout=60):
        cell_xpath, _ = self._get_cell_xpath_and_info_by_id(cell_id)
        self._view_panel.show_detail_panel(cell_xpath)
        self._detail_panel.reset_cell(with_graceful, timeout)

    def _get_cell_xpath_and_info_by_id(self, cell_id):
        cell_xpath_list = self._view_panel.get_cell_xpath_list(timeout=60)
        for cell_xpath in cell_xpath_list:
            cell_info = self._get_cell_info_by_xpath(cell_xpath)
            if cell_id == int(cell_info.get(self._GLOBAL_CELL_ID)
                              or cell_info.get(self._CELL_ID)
                              or cell_info.get(self._GSM_SECTOR_ID)):
                return cell_xpath, cell_info

    def _get_cell_info_by_xpath(self, cell_xpath):
        self._view_panel.show_detail_panel(cell_xpath)
        return self._detail_panel.get_detail_info_table()

    def get_number_of_cells(self, timeout=60):
        return len(self._view_panel.get_cell_xpath_list(timeout))

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


