class CellsPageDetailPanel(DetailPanel):
    _LOCK_OR_UNLOCK_BUTTON_XPATH = '//div[@dist-name="operationDistName"]//ui-button[contains(@a-text, "lock Cell")]'
    _RESET_BUTTON_XPATH = '//div[@dist-name="operationDistName"]//ui-button[contains(@a-text, "Reset")]'
    _LOCK_STATUS = "Lock"
    _UNLOCK_STATUS = "Unlock"
    _RESET_STATUS = "Reset"
    _ADMINISTRATIVE_STATE_XPATH = '//td[contains(text(), "Administrative state")]//following-sibling::td'

    def __init__(self, driver):
        super(CellsPageDetailPanel, self).__init__(driver)

    def _change_cell_status_on_modal(self, state, with_graceful=False, timeout=60):
        cell_modal = BlockCellModal(self.driver)
        cell_modal.wait_until_block_cell_modal_appear(timeout)
        if state == self._LOCK_STATUS:
            cell_modal.lock(timeout)
        elif state == self._UNLOCK_STATUS:
            cell_modal.unlock(timeout)
        elif state == self._RESET_STATUS:
            cell_modal.reset(with_graceful, timeout)

    def lock_cell(self, timeout):
        if self._UNLOCK_STATUS == self.get_text_by_xpath(self._LOCK_OR_UNLOCK_BUTTON_XPATH, timeout):
            raise UnexpectedElementState("Current status of cell is locked, no need to lock")

        self.click_enabled_element_after_visible((By.XPATH, self._LOCK_OR_UNLOCK_BUTTON_XPATH), timeout)
        self._change_cell_status_on_modal(self._LOCK_STATUS, timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._ADMINISTRATIVE_STATE_XPATH), 'Locked', timeout)

    def unlock_cell(self, timeout):
        if self._LOCK_STATUS == self.get_text_by_xpath(self._LOCK_OR_UNLOCK_BUTTON_XPATH, timeout):
            raise UnexpectedElementState("Current status of cell is unlock, no need to unlock")

        self.click_enabled_element_after_visible((By.XPATH, self._LOCK_OR_UNLOCK_BUTTON_XPATH), timeout)
        self._change_cell_status_on_modal(self._UNLOCK_STATUS, timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._ADMINISTRATIVE_STATE_XPATH), 'Unlocked', timeout)

    def reset_cell(self, with_graceful, timeout=60):
        self.click_enabled_element_after_visible((By.XPATH, self._RESET_BUTTON_XPATH), timeout)
        self._change_cell_status_on_modal(self._RESET_STATUS, with_graceful, timeout)
        try:
            self.wait_for_text_present_in_attribute(self._RESET_BUTTON_XPATH, 'a-title', 'Operation ongoing', timeout)
            self.wait_for_text_not_present_in_attribute(self._RESET_BUTTON_XPATH, 'a-title', 'Operation ongoing', timeout)
        except StaleElementReferenceException:
            logging.info("ingnore here, because the element will be invalid after long time waiting")

        self.wait_until_element_is_clickable(self._RESET_BUTTON_XPATH, timeout)


